def transform(grid):
    h, w = len(grid), len(grid[0])
    anchors = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]

    def nearby_count(r, c):
        return sum(
            1
            for i in range(h)
            for j in range(w)
            if grid[i][j] != 0 and (i, j) != (r, c)
            and abs(i - r) <= 2 and abs(j - c) <= 3
        )

    source = max(anchors, key=lambda p: nearby_count(*p))
    target = next(p for p in anchors if p != source)
    out = [row[:] for row in grid]
    tr, tc = target
    out[tr][tc] = 0

    sr, sc = source
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value and (r, c) != source:
                nr, nc = tr + r - sr, tc + c - sc
                if 0 <= nr < h and 0 <= nc < w:
                    out[nr][nc] = value
    return out
